"""Build the public static demo from the desktop UI. No production data is read."""
from pathlib import Path
import random, shutil

root=Path(__file__).resolve().parents[1];demo=root/'demo';assets=root/'assets'
for name in ('app.css','logo.png','app.ico'):
    shutil.copyfile(assets/name,demo/name)
html=(assets/'index.html').read_text(encoding='utf-8')
for name in ('app.css','logo.png','app.js','settings.js'):
    html=html.replace('/'+name,'./'+name)
html=html.replace('<title>轉接平台｜影像監控</title>','<title>SICK 讀碼影像監控｜互動展示</title><meta name="description" content="體驗 SICK 讀碼影像監控的最新照片、NG 檢視與 1～10 台設備設定。純瀏覽器模擬，無需安裝或連接設備。"><link rel="icon" href="./app.ico"><link rel="stylesheet" href="./demo.css">')
html=html.replace('VISION MONITOR · RUST','VISION MONITOR · DEMO')
banner='''<section class="demo-banner" aria-label="展示模式說明"><div><strong>互動展示 · 不需設備，也能體驗監控流程</strong><p>所有照片與條碼皆為合成示意資料。設定僅保存在此瀏覽器，不會連線相機、不接收 FTP，也不會修改正式程式。</p></div><div class="demo-links"><a href="https://github.com/wkltueserc20/SICK-GLS611lector-monitor" target="_blank" rel="noopener noreferrer">查看原始碼 ↗</a><a href="https://github.com/wkltueserc20/SICK-GLS611lector-monitor/releases/latest" target="_blank" rel="noopener noreferrer">下載 Windows 正式版 ↗</a></div></section>
<section class="demo-controls" aria-label="模擬操作"><div class="preset-group"><span>設備數量</span><button data-preset="1">1 台</button><button data-preset="4">4 台</button><button data-preset="10">10 台</button></div><label>模擬對象<select id="demoTarget" aria-label="模擬對象"></select></label><button data-result="ok">模擬 OK</button><button data-result="ng">模擬 NG</button><button id="demoAuto" aria-pressed="true">自動模擬：開</button></section>'''
html=html.replace('<section class="overview"',banner+'<section class="overview"')
html=html.replace('管理 1～10 台設備 · 儲存後需關閉並重新開啟程式','管理 1～10 台展示設備 · 儲存後立即套用，僅影響此瀏覽器')
html=html.replace('儲存不會中斷目前接收；重新開啟後套用。','展示設定儲存在此瀏覽器，儲存後立即套用。')
html=html.replace('所有設備皆已停用。請在「設備設定」啟用設備，儲存後重開程式。','所有展示設備皆已停用。請在「設備設定」啟用設備並儲存。')
start=html.index('<div class="helpbody">');end=html.index('</div></dialog>',start)
html=html[:start]+'''<div class="helpbody"><h3>這是什麼？</h3><p>這是 Windows Rust 監控程式的互動展示。正式版接收 SICK Lector611 Liquid Lens 的照片及 XML；這裡完全以瀏覽器產生模擬結果。</p><h3>建議體驗順序</h3><p>選擇一台或十台 → 選擇模擬對象 → 按「模擬 NG」→ 再按「模擬 OK」，觀察最新照片恢復 OK，而最近 NG 仍保留。點照片可放大及旋轉。</p><h3>設備設定</h3><p>可調整名稱、IP、FTP 埠、啟用狀態與排序。儲存後立即套用展示；正式版需重新開啟程式。匯入匯出僅處理 JSON 設定，不含照片。</p><h3>暫停的差異</h3><p>「暫停畫面」只凍結顯示，模擬仍繼續。「自動模擬：關」停止自動產生新結果，仍可手動模擬 OK／NG。</p><h3>展示資料</h3><p>示意圖片並非現場照片，圖中的點陣紋理不是可解碼條碼；條碼文字為預先產生的假資料。關閉網頁不影響任何設備。設備數量快捷鍵會重設展示設定。</p><p id="dataPath" hidden></p><strong id="limit" hidden></strong></div>'''+html[end+len('</div>'):]
html=html.replace('修改此處不會變更設備本身的網路設定；請同步設定 SOPAS 的 FTP 目的地與電腦防火牆。','這裡僅模擬設定，不會發送網路請求至設備；正式部署才需同步設定 SOPAS 與防火牆。')
html=html.replace('備份 JSON 不含照片。','備份 JSON 不含照片。本展示不會在磁碟建立照片資料夾。')
html=html.replace('背景仍接收及保存照片','展示模擬仍繼續')
html=html.replace('時間為電腦接收時間','時間為模擬產生時間')
html=html.replace('照片與 NG 合計套用每台保留上限；調低上限後，重開時會清除超額的舊照片。','展示張數僅為模擬計數，不會建立或刪除實際照片。')
html=html.replace('<script src="./app.js">','<script src="./simulator.js"></script><script src="./app.js">')
html=html.replace('</body>','<script src="./controls.js"></script></body>')
(demo/'index.html').write_text(html,encoding='utf-8')
js=(assets/'app.js').read_text(encoding='utf-8').replace("fetch('/api/status'","window.demoAPI('/api/status'")
js=js.replace("img.src='/'+encodeURIComponent(d.file)","img.src='./images/'+encodeURIComponent(d.file)")
js=js.replace("'接收服務正常'","(window.demoRunning?'展示模式 · 自動模擬中':'展示模式 · 手動模擬')")
(demo/'app.js').write_text('// Generated by scripts/build_demo.py from assets/app.js\n'+js,encoding='utf-8')
js=(assets/'settings.js').read_text(encoding='utf-8').replace("fetch('/api/config'","window.demoAPI('/api/config'")
js=js.replace('已儲存。請關閉並重新開啟程式後套用；目前接收仍使用舊設定。已自動備份前一次設定為 config.previous.json。','已套用展示設定，僅影響此瀏覽器。正式程式與設備設定均未變更。')
js=js.replace("$('#pendingSettings').hidden=false","$('#pendingSettings').hidden=true")
js=js.replace("settingMessage('已套用展示設定，僅影響此瀏覽器。正式程式與設備設定均未變更。');", "settingMessage(body.local_saved?'已套用展示設定，僅影響此瀏覽器。正式程式與設備設定均未變更。':'已套用到本次展示；瀏覽器限制儲存，因此重新整理後不會保留。');")
(demo/'settings.js').write_text('// Generated by scripts/build_demo.py from assets/settings.js\n'+js,encoding='utf-8')
images=demo/'images';images.mkdir(exist_ok=True)
for i in range(4):
 for result in ('ok','ng'):
    rng=random.Random(611+i);color='#80d6a7' if result=='ok' else '#ff8494'
    dots=''.join(f'<rect x="{254+x*7}" y="{117+y*7}" width="7" height="7" fill="#14191d"/>' for y in range(17) for x in range(17) if rng.random()>.49)
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="720" height="420" viewBox="0 0 720 420"><defs><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#6d7379"/><stop offset=".45" stop-color="#333c42"/><stop offset="1" stop-color="#778087"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="{'2.2' if result=='ng' else '0'}"/></filter><pattern id="lines" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 0H8" stroke="#a9b1b8" stroke-opacity=".1"/></pattern></defs><rect width="720" height="420" fill="#0c1218"/><path d="M0 84H720M0 350H720" stroke="#35434f" stroke-width="16"/><rect x="130" y="45" width="460" height="325" rx="16" fill="url(#metal)"/><rect x="130" y="45" width="460" height="325" rx="16" fill="url(#lines)"/>{''.join(f'<circle cx="{x}" cy="{y}" r="13" fill="#1e272e" stroke="#8a959e" stroke-width="3"/><path d="M{x-6} {y}h12" stroke="#70808b"/>' for x,y in ((155,70),(565,70),(155,344),(565,344)))}<g filter="url(#blur)"><rect x="244" y="107" width="140" height="140" rx="3" fill="#c8ccce"/>{dots}</g><rect x="235" y="98" width="158" height="158" fill="none" stroke="{color}" stroke-width="3" stroke-dasharray="{'10 6' if result=='ng' else '0'}"/><text x="412" y="155" font-family="monospace" font-size="20" fill="{color}">{'OK' if result=='ok' else 'NoRead'}</text><text x="412" y="183" font-family="monospace" font-size="12" fill="#d1dce5">SAMPLE {i+1:02}</text><text x="220" y="300" font-family="monospace" font-size="24" fill="#d0d5d8">DEMO · CT-0611</text><rect x="0" y="0" width="720" height="32" fill="#152430"/><text x="18" y="22" font-family="monospace" font-size="12" fill="#a1b9ca">SIMULATED IMAGE · NOT A REAL CAMERA CAPTURE</text><text x="18" y="399" font-family="monospace" font-size="13" fill="#a1b9ca">SYNTHETIC TEXTURE / NON-SCANNABLE / {'NO READ' if result=='ng' else 'READ OK'}</text></svg>'''
    (images/f'sample-{result}-{i}.svg').write_text(svg,encoding='utf-8')
(demo/'.nojekyll').touch()
print('Built static demo with synthetic assets; desktop application unchanged')
